public class DatasetUtilities_iterateDomainBounds_TriageGen0Test {

    @Mock
    private XYDataset mockDataset;

    @Mock
    private IntervalXYDataset mockIntervalDataset;

    public DatasetUtilities_iterateDomainBounds_TriageGen0Test() {
        MockitoAnnotations.openMocks(this);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testIterateDomainBounds_NullDataset() {
        DatasetUtilities.iterateDomainBounds(null, false);
    }

    @Test
    public void testIterateDomainBounds_StandardXYDataset_NormalValues() {
        // Setup: 1 series, 2 items
        when(mockDataset.getSeriesCount()).thenReturn(1);
        when(mockDataset.getItemCount(0)).thenReturn(2);
        when(mockDataset.getXValue(0, 0)).thenReturn(10.0);
        when(mockDataset.getXValue(0, 1)).thenReturn(20.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockDataset, false);

        assertEquals(10.0, result.getLower(), 1e-9);
        assertEquals(20.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_StandardXYDataset_WithNaN() {
        // Setup: 1 series, 3 items (one is NaN)
        when(mockDataset.getSeriesCount()).thenReturn(1);
        when(mockDataset.getItemCount(0)).thenReturn(3);
        when(mockDataset.getXValue(0, 0)).thenReturn(5.0);
        when(mockDataset.getXValue(0, 1)).thenReturn(Double.NaN);
        when(mockDataset.getXValue(0, 2)).thenReturn(15.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockDataset, false);

        assertEquals(5.0, result.getLower(), 1e-9);
        assertEquals(15.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_IntervalXYDataset_IncludeInterval_True() {
        // Setup: 1 series, 2 items
        when(mockIntervalDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalDataset.getItemCount(0)).thenReturn(2);

        // Item 0: [1.0, 5.0]
        when(mockIntervalDataset.getStartXValue(0, 0)).thenReturn(1.0);
        when(mockIntervalDataset.getEndXValue(0, 0)).thenReturn(5.0);
        // Item 1: [10.0, 20.0]
        when(mockIntervalDataset.getStartXValue(0, 1)).thenReturn(10.0);
        when(mockIntervalDataset.getEndXValue(0, 1)).thenReturn(20.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockIntervalDataset, true);

        assertEquals(1.0, result.getLower(), 1e-9);
        assertEquals(20.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_IntervalXYDataset_IncludeInterval_True_WithNaN() {
        // Setup: 1 series, 2 items (one interval has NaN)
        when(mockIntervalDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalDataset.getItemCount(0)).thenReturn(2);

        // Item 0: [1.0, 5.0]
        when(mockIntervalDataset.getStartXValue(0, 0)).thenReturn(1.0);
        when(mockIntervalDataset.getEndXValue(0, 0)).thenReturn(5.0);
        // Item 1: [NaN, 20.0]
        when(mockIntervalDataset.getStartXValue(0, 1)).thenReturn(Double.NaN);
        when(mockIntervalDataset.getEndXValue(0, 1)).thenReturn(20.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockIntervalDataset, true);

        assertEquals(1.0, result.getLower(), 1e-9);
        assertEquals(20.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_IntervalXYDataset_IncludeInterval_False() {
        // Even if it is an IntervalXYDataset, if includeInterval is false, it uses getXValue
        // Mocking the same object to behave like standard XYDataset for this branch
        when(mockIntervalDataset.getSeriesCount()).thenReturn(1);
        when(mockIntervalDataset.getItemCount(0)).thenReturn(1);
        when(mockIntervalDataset.getXValue(0, 0)).thenReturn(50.0);

        Range result = DatasetUtilities.iterateDomainBounds(mockIntervalDataset, false);

        assertEquals(50.0, result.getLower(), 1e-9);
        assertEquals(50.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIterateDomainBounds_EmptyDataset() {
        when(mockDataset.getSeriesCount()).thenReturn(0);

        Range result = DatasetUtilities.iterateDomainBounds(mockDataset, false);

        assertNull(result);
    }

    @Test
    public void testIterateDomainBounds_DatasetWithOnlyNaN() {
        when(mockDataset.getSeriesCount()).thenReturn(1);
        when(mockDataset.getItemCount(0)).thenReturn(1);
        when(mockDataset.getXValue(0, 0)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateDomainBounds(mockDataset, false);

        assertNull(result);
    }

    @Test
    public void testIterateDomainBounds_MinimumGreaterThanMaximum() {
        // This case is mathematically difficult to hit with Math.min/max unless 
        // variables are manipulated, but according to logic: if (minimum > maximum) return null;
        // Since we start with Infinity and -Infinity, this only happens if no valid numbers are found.
        // However, we can simulate it if the logic allowed it. 
        // Given the code structure, if at least one non-NaN is found, min <= max.
        // If no non-NaN is found, min (Inf) > max (-Inf), returning null.

        when(mockDataset.getSeriesCount()).thenReturn(1);
        when(mockDataset.getItemCount(0)).thenReturn(1);
        when(mockDataset.getXValue(0, 0)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateDomainBounds(mockDataset, false);
        assertNull(result);
    }
}
